import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { dashboardApi, machineApi } from '../api/client';
import DashboardCard from '../components/DashboardCard';
import StatusChart from '../components/StatusChart';
import ActivityFeed from '../components/ActivityFeed';
import HealthTrendChart from '../components/HealthTrendChart';
import ProductionChart from '../components/ProductionChart';
import EnergyCard from '../components/EnergyCard';
import UpcomingMaintenanceTable from '../components/UpcomingMaintenanceTable';
import AlertsPanel from '../components/AlertsPanel';
import CriticalityChart from '../components/CriticalityChart';
import LiveTelemetryWidget from '../components/LiveTelemetryWidget';
import SkeletonCard from '../components/SkeletonCard';
import KPIDrawer from '../components/KPIDrawer';
import MachineDetailsModal from '../components/MachineDetailsModal';
import {
  Server,
  PlayCircle,
  PauseCircle,
  Wrench,
  AlertTriangle,
  ArrowRight,
  Plus,
  Radio,
  Factory,
  Activity,
  Gauge,
  Thermometer,
  Zap,
  Award,
  Sparkles,
  Download,
} from 'lucide-react';

const DashboardPage = () => {
  const navigate = useNavigate();
  const [summary, setSummary] = useState(null);
  const [fleetStatus, setFleetStatus] = useState(null);
  const [recentActivities, setRecentActivities] = useState([]);
  const [machinesList, setMachinesList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [liveConnected, setLiveConnected] = useState(false);

  // Drawer & Detail View States
  const [activeDrawerCategory, setActiveDrawerCategory] = useState(null);
  const [selectedMachineDetail, setSelectedMachineDetail] = useState(null);

  useEffect(() => {
    fetchDashboardSummary();
    fetchFleetStatus();
    fetchRecentActivity();
    fetchAllMachines();

    // 30s fallback polling
    const pollInterval = setInterval(() => {
      fetchDashboardSummary();
      fetchFleetStatus();
      fetchRecentActivity();
      fetchAllMachines();
    }, 30000);

    // Server-Sent Events (SSE) Live Telemetry Stream — Real-Time Push directly from Assets Backend
    const apiBaseUrl = process.env.REACT_APP_API_BASE_URL || 'http://localhost:5000/api';
    let eventSource;
    try {
      eventSource = new EventSource(`${apiBaseUrl}/dashboard/live`);

      eventSource.onopen = () => {
        setLiveConnected(true);
      };

      eventSource.onmessage = (e) => {
        try {
          const liveData = JSON.parse(e.data);
          if (liveData.summary) {
            setSummary(liveData.summary);
          }
          if (liveData.fleet) {
            setFleetStatus(liveData.fleet);
          }
          if (liveData.activities) {
            setRecentActivities(liveData.activities);
          }
        } catch (err) {
          console.error('Error parsing live stream data:', err);
        }
      };

      eventSource.onerror = () => {
        setLiveConnected(false);
        eventSource.close();
      };
    } catch (err) {
      console.warn('SSE connection unavailable, using fallback polling.', err);
    }

    return () => {
      clearInterval(pollInterval);
      if (eventSource) eventSource.close();
    };
  }, []);

  const fetchDashboardSummary = async () => {
    try {
      setLoading(true);
      const res = await dashboardApi.getSummary();
      if (res.data.success) {
        setSummary(res.data.data);
      }
    } catch (err) {
      console.error('Failed to fetch dashboard summary:', err);
    } finally {
      setLoading(false);
    }
  };

  const fetchFleetStatus = async () => {
    try {
      const res = await dashboardApi.getFleetStatus();
      if (res.data.success) {
        setFleetStatus(res.data.data);
      }
    } catch (err) {
      console.error('Failed to fetch fleet status:', err);
    }
  };

  const fetchRecentActivity = async () => {
    try {
      const res = await dashboardApi.getRecentActivity();
      if (res.data.success) {
        setRecentActivities(res.data.data);
      }
    } catch (err) {
      console.error('Failed to fetch recent activity:', err);
    }
  };

  const fetchAllMachines = async () => {
    try {
      const res = await machineApi.getAll();
      if (res.data.success) {
        setMachinesList(res.data.data);
      }
    } catch (err) {
      console.error('Failed to fetch machines list:', err);
    }
  };

  // Group machines by Plant for Plant Leaderboard Widget
  const plantLeaderboard = [
    { name: 'TexTwin Primary Mill', hub: 'Coimbatore Hub', count: 5, efficiency: '98.2%', status: 'Optimal' },
    { name: 'TexTwin Synthetic Complex', hub: 'Surat Hub', count: 5, efficiency: '97.8%', status: 'Optimal' },
    { name: 'TexTwin Eco-Cotton Mill', hub: 'Salem Hub', count: 2, efficiency: '96.5%', status: 'Optimal' },
    { name: 'TexTwin Silk & Jacquard Unit', hub: 'Kanchipuram Hub', count: 2, efficiency: '96.1%', status: 'Optimal' },
    { name: 'TexTwin Denim Weaving', hub: 'Gujarat Hub', count: 3, efficiency: '94.8%', status: 'Normal' },
    { name: 'TexTwin Technical Textiles', hub: 'Tirupur Facility', count: 3, efficiency: '88.4%', status: 'Service' },
  ];

  return (
    <div>
      {/* Top Header */}
      <div className="page-header">
        <div className="page-title-group">
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <h1>Asset Operations Dashboard</h1>
            {liveConnected && (
              <span
                style={{
                  fontSize: '0.75rem',
                  padding: '0.2rem 0.6rem',
                  borderRadius: '12px',
                  background: 'var(--status-running-bg)',
                  color: 'var(--status-running)',
                  border: '1px solid rgba(5, 150, 105, 0.3)',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.35rem',
                  fontWeight: '800',
                }}
              >
                <Radio size={12} className="dot" /> SSE LIVE STREAM
              </span>
            )}
          </div>
          <p>Real-Time Operations Across 6 Factory Plants, 10 Production Lines, & 20 Weaving Looms</p>
        </div>

        <div style={{ display: 'flex', gap: '0.75rem', flexWrap: 'wrap' }}>
          <button
            className="btn btn-secondary"
            onClick={() => {
              const csvContent = 'data:text/csv;charset=utf-8,Plant,Hub,Looms,Efficiency,Status\n' +
                plantLeaderboard.map(p => `"${p.name}","${p.hub}",${p.count},"${p.efficiency}","${p.status}"`).join('\n');
              const encodedUri = encodeURI(csvContent);
              const link = document.createElement('a');
              link.setAttribute('href', encodedUri);
              link.setAttribute('download', 'TexTwin_Operations_Report.csv');
              document.body.appendChild(link);
              link.click();
              document.body.removeChild(link);
            }}
          >
            <Download size={16} /> Export Operations CSV
          </button>
          <button className="btn btn-secondary" onClick={() => navigate('/what-if')}>
            <Sparkles size={16} style={{ color: 'var(--accent-primary)' }} /> What-If AI Simulator
          </button>
          <button className="btn btn-secondary" onClick={() => navigate('/assets')}>
            View All Assets <ArrowRight size={16} />
          </button>
          <button className="btn btn-primary" onClick={() => navigate('/assets/new')}>
            <Plus size={16} /> Add Asset
          </button>
        </div>
      </div>

      {/* Row 1: 5 Interactive Clickable Metric Summary Cards */}
      {loading && !summary ? (
        <div className="dashboard-grid">
          <SkeletonCard height="110px" />
          <SkeletonCard height="110px" />
          <SkeletonCard height="110px" />
          <SkeletonCard height="110px" />
          <SkeletonCard height="110px" />
        </div>
      ) : (
        <div className="dashboard-grid">
          <DashboardCard
            title="Total Machine Assets"
            value={summary?.totalAssets || 20}
            subtitle="20 Weaving Looms Across 6 Plants"
            icon={Server}
            colorClass="icon-blue"
            onClick={() => setActiveDrawerCategory('total')}
          />
          <DashboardCard
            title="Running Assets"
            value={summary?.running || 17}
            subtitle="Status = RUNNING"
            icon={PlayCircle}
            colorClass="icon-green"
            onClick={() => setActiveDrawerCategory('running')}
          />
          <DashboardCard
            title="Idle Assets"
            value={summary?.idle || 2}
            subtitle="Status = IDLE"
            icon={PauseCircle}
            colorClass="icon-yellow"
            onClick={() => setActiveDrawerCategory('idle')}
          />
          <DashboardCard
            title="Under Maintenance"
            value={summary?.maintenance || 1}
            subtitle="Status = MAINTENANCE"
            icon={Wrench}
            colorClass="icon-red"
            onClick={() => setActiveDrawerCategory('maintenance')}
          />
          <DashboardCard
            title="High Criticality"
            value={summary?.highCriticality || 11}
            subtitle="Criticality = HIGH"
            icon={AlertTriangle}
            colorClass="icon-purple"
            onClick={() => setActiveDrawerCategory('critical')}
          />
        </div>
      )}

      {/* Row 2: Fleet Status Donut + Activity Feed + Criticality Distribution */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))',
          gap: '1.25rem',
          marginBottom: '1.75rem',
          alignItems: 'stretch',
        }}
      >
        {/* Panel 1: Fleet Status Breakdown */}
        <div className="glass-card" style={{ padding: '1.25rem' }}>
          <StatusChart
            running={fleetStatus?.running || summary?.running || 17}
            idle={fleetStatus?.idle || summary?.idle || 2}
            maintenance={fleetStatus?.maintenance || summary?.maintenance || 1}
          />
        </div>

        {/* Panel 2: Recent Activity Feed */}
        <div className="glass-card" style={{ padding: '1.25rem' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.75rem' }}>
            <div>
              <h3 style={{ fontSize: '1rem', fontWeight: '800', color: 'var(--text-primary)' }}>
                Recent Activity Feed
              </h3>
              <span style={{ fontSize: '0.74rem', color: 'var(--text-muted)', fontWeight: '600' }}>
                Latest 4 Operational Audit Events
              </span>
            </div>
            <span className="badge badge-low" style={{ fontWeight: '800', fontSize: '0.7rem' }}>Audit Trail</span>
          </div>
          <ActivityFeed activities={recentActivities} />
        </div>

        {/* Panel 3: Asset Criticality Distribution */}
        <CriticalityChart
          high={summary?.highCriticality || 11}
          medium={Math.max(0, (summary?.totalAssets || 20) - (summary?.highCriticality || 11) - 3)}
          low={3}
        />
      </div>

      {/* NEW ROW 2.5: 6 FACTORY PLANTS EFFICIENCY LEADERBOARD WIDGET */}
      <div className="glass-card" style={{ padding: '1.5rem', marginBottom: '1.75rem' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.25rem' }}>
          <div>
            <h3 style={{ fontSize: '1.1rem', fontWeight: '800', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <Factory size={20} style={{ color: 'var(--accent-primary)' }} /> 6 Factory Plants Operational Leaderboard
            </h3>
            <span style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', fontWeight: '700' }}>
              Real-Time Fleet Efficiency, Weaving Loom Allocations, & Operational Status
            </span>
          </div>
          <span className="badge badge-low" style={{ fontWeight: '800' }}>6 Active Plants</span>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '1rem' }}>
          {plantLeaderboard.map((plant, idx) => (
            <div key={idx} style={{ padding: '1rem', background: 'var(--bg-primary)', borderRadius: 'var(--radius-sm)', border: '1px solid var(--border-subtle)' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                <span style={{ fontSize: '0.78rem', fontWeight: '800', color: 'var(--accent-primary)', textTransform: 'uppercase' }}>
                  {plant.hub}
                </span>
                <span className={`badge badge-${plant.status === 'Optimal' ? 'running' : plant.status === 'Normal' ? 'idle' : 'maintenance'}`}>
                  {plant.status}
                </span>
              </div>
              <div style={{ fontSize: '1.02rem', fontWeight: '800', color: 'var(--text-primary)', marginTop: '4px' }}>
                {plant.name}
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '0.75rem', fontSize: '0.85rem', fontWeight: '800' }}>
                <span style={{ color: 'var(--text-secondary)' }}>Looms: {plant.count}</span>
                <span style={{ color: 'var(--status-running)' }}>Efficiency: {plant.efficiency}</span>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Row 2.8: LIVE IOT SENSOR TELEMETRY FEEDS WIDGET */}
      <LiveTelemetryWidget />

      {/* Row 3: Machine Health Trend Line Chart + Production Output Bar Chart */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(400px, 1fr))',
          gap: '1.25rem',
          marginBottom: '1.75rem',
        }}
      >
        <HealthTrendChart />
        <ProductionChart />
      </div>

      {/* Row 4: Energy Consumption Single Card */}
      <div style={{ marginBottom: '1.75rem' }}>
        <EnergyCard />
      </div>

      {/* Row 5: Active Alerts Panel + Upcoming Maintenance Table */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(450px, 1fr))',
          gap: '1.25rem',
        }}
      >
        <AlertsPanel />
        <UpcomingMaintenanceTable />
      </div>

      {/* Right-Side Sliding Drawer for Clicked KPI Card */}
      {activeDrawerCategory && (
        <KPIDrawer
          category={activeDrawerCategory}
          machines={machinesList}
          onClose={() => setActiveDrawerCategory(null)}
          onSelectMachine={(m) => {
            setSelectedMachineDetail(m);
          }}
        />
      )}

      {/* 7-Section Machine Details Inspection View */}
      {selectedMachineDetail && (
        <MachineDetailsModal
          machine={selectedMachineDetail}
          onClose={() => setSelectedMachineDetail(null)}
        />
      )}
    </div>
  );
};

export default DashboardPage;
